// FRW-007 criterion 6 (12 §13, "Form mode without a workflow"; 05 §3.1; owner decision 5a of
// 2026-11-15): the roles a user may fill outside a workflow come from a token claim, `wfr` by
// default and configurable per tenant, and reach `access.fill.roles` of `ch.opened`. Every key is
// generated by the test.
import { randomUUID } from 'node:crypto';
import { computeAccess, type PermissionState } from '@docedit/authority';
import { uuid7 } from '@docedit/model';
import { toAccess } from '@docedit/protocol/bridge';
import { beforeEach, describe, expect, it } from 'vitest';
import { signJws } from '../../src/control-plane/jwt.ts';
import { MemoryTenantRegistry } from '../../src/control-plane/tenants.ts';
import { signingKey, TokenService } from '../../src/control-plane/tokens.ts';
import { MemoryUserDirectory } from '../../src/control-plane/users.ts';
import { hostKey } from './support.ts';

const SERVICE = 'https://docs.example.test';

const perms = (documentState: 'active' | 'locked' = 'active'): PermissionState =>
  ({
    revision: 1,
    grants: [],
    regionStates: new Map(),
    leases: [],
    documentState,
    workflowActive: false,
  }) as unknown as PermissionState;

describe('the fill roles claim without a workflow (FRW-007 criterion 6)', () => {
  const now = Date.now();
  const host = hostKey('ES256');
  const doc = uuid7();
  let tenant: string;
  let registry: MemoryTenantRegistry;

  beforeEach(async () => {
    tenant = randomUUID();
    registry = new MemoryTenantRegistry(() => now);
    await registry.putTenant(tenant, 't');
    await registry.addKey(tenant, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
  });

  const service = (fillRolesClaim?: (tenant: string) => string) =>
    new TokenService({
      registry,
      users: new MemoryUserDirectory(),
      serviceId: SERVICE,
      signing: signingKey(undefined, 'svc'),
      now: () => now,
      ...(fillRolesClaim ? { fillRolesClaim } : {}),
    });

  const sign = (claims: Record<string, unknown> = {}) => {
    const iat = Math.floor(now / 1000);
    return signJws(
      { alg: host.alg, typ: 'JWT', kid: host.kid },
      {
        iss: 'host',
        aud: SERVICE,
        iat,
        exp: iat + 300,
        jti: uuid7(),
        tid: tenant,
        sub: 'u-1',
        docs: { [doc]: 'filler' },
        ...claims,
      },
      host.privateKey,
    );
  };

  /** The `access` of `ch.opened` for the verified token. */
  async function opened(tokens: TokenService, token: string, p = perms()) {
    const id = await tokens.verifyUser(token);
    const access = computeAccess(id.connection, [], p, now);
    return toAccess(access, id.connection, p, [], p.revision, 1);
  }

  it('gives access.fill.roles equal to the roles of the claim, and the participant is active', async () => {
    const out = await opened(service(), sign({ wfr: ['role_tenant', 'role_witness'] }));
    // Without a `wfp` claim the user stands in for the participant (the per-tenant surrogate here).
    expect(out.fill).toEqual({
      participant: expect.any(String),
      roles: ['role_tenant', 'role_witness'],
      active: true,
    });
  });

  it('is null for a token without the claim, and for an empty claim', async () => {
    expect((await opened(service(), sign())).fill).toBeNull();
    expect((await opened(service(), sign({ wfr: [] }))).fill).toBeNull();
  });

  it('lists each role once, in token order', async () => {
    const out = await opened(service(), sign({ wfr: ['b', 'a', 'b'] }));
    expect(out.fill?.roles).toEqual(['b', 'a']);
  });

  it('reads the claim the tenant names, and ignores the default name then', async () => {
    const tokens = service((t) => (t === tenant ? 'fill_roles' : 'wfr'));
    const named = await opened(tokens, sign({ fill_roles: ['role_tenant'] }));
    expect(named.fill?.roles).toEqual(['role_tenant']);
    expect((await opened(tokens, sign({ wfr: ['role_tenant'] }))).fill).toBeNull();
  });

  it('reads the default name `wfr` for a tenant that names none', async () => {
    const tokens = service(() => 'wfr');
    expect((await opened(tokens, sign({ wfr: ['r'] }))).fill?.roles).toEqual(['r']);
  });

  it('refuses a claim that is not an array of identifiers', async () => {
    for (const bad of ['role_tenant', [1], [''], { a: 1 }])
      await expect(service().verifyUser(sign({ wfr: bad }))).rejects.toMatchObject({
        code: 'unauthenticated',
      });
  });

  it('mints the roles of the wfr member under the claim the tenant names (FRW-066 criterion 5)', async () => {
    const asked = {
      sub: 'u-mint',
      docs: { [doc]: 'filler' as const },
      wfr: ['role_tenant', 'role_witness'],
    };
    const claims = (token: string) =>
      JSON.parse(Buffer.from(token.split('.')[1]!, 'base64url').toString('utf8')) as Record<
        string,
        unknown
      >;
    const plain = await service().mint(tenant, asked);
    expect(claims(plain.token)['wfr']).toEqual(['role_tenant', 'role_witness']);
    // Another claim name for the tenant: the roles are written there, and the default is not.
    const named = service((t) => (t === tenant ? 'fill_roles' : 'wfr'));
    const other = claims((await named.mint(tenant, asked)).token);
    expect(other['fill_roles']).toEqual(['role_tenant', 'role_witness']);
    expect(other['wfr']).toBeUndefined();
    // Without the member there is no claim.
    const none = await service().mint(tenant, { sub: 'u-mint', docs: { [doc]: 'filler' } });
    expect(claims(none.token)['wfr']).toBeUndefined();
    // A role that is not an opaque identifier is refused.
    await expect(service().mint(tenant, { ...asked, wfr: [' bad role'] })).rejects.toMatchObject({
      code: 'validation_failed',
    });
  });

  it('leaves the fill right to the document state: on a locked document the fill object is null', async () => {
    const out = await opened(service(), sign({ wfr: ['role_tenant'] }), perms('locked'));
    expect(out.fill).toBeNull();
  });

  it('does not change the identity of a token that carries the claim', async () => {
    const tokens = service();
    const bare = await tokens.verifyUser(sign());
    const withRoles = await tokens.verifyUser(sign({ wfr: ['role_tenant'] }));
    expect(withRoles.sub).toBe(bare.sub);
    expect(withRoles.connection.role).toBe(bare.connection.role);
    expect(withRoles.connection.groups).toEqual(bare.connection.groups);
  });
});
